	@Test
	void boundedVariantDispatcherRoutesMergesAndFallsBackDeterministically() throws Exception {
		LmdbPlanDecisionCache cache = new LmdbPlanDecisionCache(8, 1024 * 1024L);
		Fixture fixture = fixture(1L);
		assertTrue(cache.publishBuild(fixture.publication(fixture.evidence())));

		long version = familyVersion(cache, fixture, 5.0d);
		assertTrue(publishVariant(cache, fixture, version, 2L, guard(0.0d, 10.0d), "selective", 4.0d));
		version = familyVersion(cache, fixture, 50.0d);
		assertTrue(publishVariant(cache, fixture, version, 3L, guard(11.0d, 100.0d), "broad", 8.0d));

		assertUseFingerprint(cache.lookupFamily(fixture.familyKey(), fixture.request(fixture.evidence(), 5.0d)),
				"selective", 2L);
		assertUseFingerprint(cache.lookupFamily(fixture.familyKey(), fixture.request(fixture.evidence(), 50.0d)),
				"broad", 3L);
		LmdbPlanDecisionCache.UseAndRefresh fallback = assertInstanceOf(
				LmdbPlanDecisionCache.UseAndRefresh.class,
				cache.lookupFamily(fixture.familyKey(), fixture.request(fixture.evidence(), 500.0d)));
		assertEquals(1L, fallback.variantId());
		assertEquals("robust-fallback-outside-specialized-regions", fallback.reason());

		version = familyVersion(cache, fixture, 15.0d);
		assertTrue(publishVariant(cache, fixture, version, 4L, guard(10.0d, 20.0d), "selective", 4.0d),
				"an adjacent region with the same executable champion should merge");
		assertUseFingerprint(cache.lookupFamily(fixture.familyKey(), fixture.request(fixture.evidence(), 15.0d)),
				"selective", 2L);

		version = familyVersion(cache, fixture, 150.0d);
		assertTrue(publishVariant(cache, fixture, version, 5L, guard(101.0d, 200.0d), "middle", 9.0d));
		version = familyVersion(cache, fixture, 250.0d);
		assertFalse(publishVariant(cache, fixture, version, 6L, guard(201.0d, 300.0d), "overflow", 10.0d),
				"the robust fallback and three specialized variants exhaust the default four-variant budget");
	}

	@Test
	void refreshSchedulerIsSingleFlightPriorityOrderedAndStopsOnClose() throws Exception {
		LmdbPlanDecisionCache cache = new LmdbPlanDecisionCache(8, 1024 * 1024L);
		Fixture blockerFixture = fixture("blocker", 1L);
		Fixture lowFixture = fixture("low", 1L);
		Fixture highFixture = fixture("high", 1L);
		assertTrue(cache.publishBuild(blockerFixture.publication(blockerFixture.evidence())));
		assertTrue(cache.publishBuild(lowFixture.publication(lowFixture.evidence())));
		assertTrue(cache.publishBuild(highFixture.publication(highFixture.evidence())));

		CountDownLatch blockerStarted = new CountDownLatch(1);
		CountDownLatch releaseBlocker = new CountDownLatch(1);
		CountDownLatch queuedCompleted = new CountDownLatch(2);
		List<String> order = new CopyOnWriteArrayList<>();
		Runnable blocker = () -> {
			blockerStarted.countDown();
			try {
				releaseBlocker.await();
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
			}
		};
		assertTrue(scheduleRefresh(cache, blockerFixture, 1.0d, 0.01d, 1.0d, 1.0d, blocker));
		assertTrue(blockerStarted.await(5L, TimeUnit.SECONDS));
		assertFalse(scheduleRefresh(cache, blockerFixture, 100.0d, 0.01d, 1.0d, 1.0d, () -> {
		}), "a family/variant may own only one refresh claim");
		assertTrue(scheduleRefresh(cache, lowFixture, 1.0d, 0.01d, 1.0d, 100.0d, () -> {
			order.add("low");
			queuedCompleted.countDown();
		}));
		assertTrue(scheduleRefresh(cache, highFixture, 10.0d, 0.01d, 1.0d, 1.0d, () -> {
			order.add("high");
			queuedCompleted.countDown();
		}));
		releaseBlocker.countDown();
		assertTrue(queuedCompleted.await(5L, TimeUnit.SECONDS));
		assertEquals(List.of("high", "low"), order);

		cache.close();
		assertFalse(Thread.getAllStackTraces()
				.keySet()
				.stream()
				.anyMatch(thread -> thread.isAlive() && thread.getName().startsWith("rdf4j-lmdb-plan-refresh-")));
	}

