	@SuppressWarnings("unchecked")
	private static LmdbPlanDecisionCache.FamilyVersion currentFamilyVersion(LmdbPlanDecisionCache cache,
			LmdbPlanDecisionCache.PlanFamilyKey familyKey) throws Exception {
		var field = LmdbPlanDecisionCache.class.getDeclaredField("families");
		field.setAccessible(true);
		var families = (java.util.Map<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.PlanFamily>) field
				.get(cache);
		return families.get(familyKey).current().get();
	}

	@SuppressWarnings("unchecked")
	private static void installAdditionalExactAliasAndCheckpoint(LmdbPlanDecisionCache cache,
			LmdbPlanDecisionCache.PlanFamilyKey familyKey, LmdbPlanDecisionCache.ExactInvocationKey exactKey,
			long variantId, long planVersion, Object checkpoint) throws Exception {
		var familiesField = LmdbPlanDecisionCache.class.getDeclaredField("families");
		familiesField.setAccessible(true);
		Map<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.PlanFamily> families = (Map<LmdbPlanDecisionCache.PlanFamilyKey, LmdbPlanDecisionCache.PlanFamily>) familiesField
				.get(cache);
		LmdbPlanDecisionCache.PlanFamily family = families.get(familyKey);
		LmdbPlanDecisionCache.FamilyVersion observed = family.current().get();
		Map<LmdbPlanDecisionCache.ExactInvocationKey, LmdbPlanDecisionCache.ExactAlias> aliases = new LinkedHashMap<>(
				observed.exactAliases());
		LmdbPlanDecisionCache.ExactAlias alias = new LmdbPlanDecisionCache.ExactAlias(
				observed.version(), variantId, planVersion);
		aliases.put(exactKey, alias);
		family.current()
				.set(new LmdbPlanDecisionCache.FamilyVersion(observed.version(), observed.semanticValidity(),
						observed.semanticDependencies(), observed.dispatcher(), checkpoint, aliases,
						observed.publicationEvidenceEpoch(), observed.retainedBytes()));
		var aliasesField = LmdbPlanDecisionCache.class.getDeclaredField("exactAliases");
		aliasesField.setAccessible(true);
		((Map<LmdbPlanDecisionCache.ExactInvocationKey, LmdbPlanDecisionCache.ExactAlias>) aliasesField.get(cache))
				.put(exactKey, alias);
	}

	private static boolean scheduleRefresh(LmdbPlanDecisionCache cache, Fixture fixture, double requestRate,
			double expectedRegret, double probabilitySearchHelps, double remainingCost, Runnable task)
			throws Exception {
		Method method = Arrays.stream(LmdbPlanDecisionCache.class.getDeclaredMethods())
				.filter(candidate -> candidate.getName().equals("scheduleRefresh"))
				.findFirst()
				.orElseThrow();
		Constructor<?> constructor = method.getParameterTypes()[0].getDeclaredConstructors()[0];
		Object request = constructor.newInstance(fixture.familyKey(), 1L, requestRate, expectedRegret,
				probabilitySearchHelps, remainingCost, task);
		return (boolean) method.invoke(cache, request);
	}

	private static ThreadPoolExecutor refreshExecutor(LmdbPlanDecisionCache cache) throws Exception {
		var field = LmdbPlanDecisionCache.class.getDeclaredField("refreshExecutor");
		field.setAccessible(true);
		return (ThreadPoolExecutor) field.get(cache);
	}

	private static void awaitCompletedRefreshTasks(LmdbPlanDecisionCache cache, long expected) throws Exception {
		ThreadPoolExecutor executor = refreshExecutor(cache);
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5L);
		while (executor.getCompletedTaskCount() < expected && System.nanoTime() < deadline) {
			Thread.onSpinWait();
		}
		assertEquals(expected, executor.getCompletedTaskCount(), "detached refresh did not complete");
	}

	private static long familyVersion(LmdbPlanDecisionCache cache, Fixture fixture, double cardinality) {
		LmdbPlanDecisionCache.LookupDecision decision = cache.lookupFamily(fixture.familyKey(),
				fixture.request(fixture.evidence(), cardinality));
		return decision instanceof LmdbPlanDecisionCache.Use use
				? use.familyVersion()
				: ((LmdbPlanDecisionCache.UseAndRefresh) decision).familyVersion();
	}

